import {OPS,NAMES,STAGES,metrics,priorities,growth,selectStudents,status,csv,validate} from './model.mjs';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const display=n=>n===null?'No data':`${Math.round(n)}%`;
const gameNames={horse:'Horse Race',dragon:'Dragon Quest',invaders:'Star Defender',pong:'Ping-Pong Rally'};
/** Mount the supplied template in a document or isolated root. Returns destroy(). */
export async function mountDashboard(root,{adapter,initialRole='teacher'}={}){
 const $=id=>root.querySelector('#'+id),controller=new AbortController(),listeners=[];let data,role=initialRole,group=null,selectedId=null;
 const onDynamic=(el,event,fn)=>{el['on'+event]=fn;};
 const on=(el,event,fn)=>{el.addEventListener(event,fn);listeners.push(()=>el.removeEventListener(event,fn));};
 const names=key=>new Map(data[key].map(x=>[x.id,x]));let schoolMap,classMap,factMap;
 const options=items=>items.map(([v,label])=>`<option value="${escape(v)}">${escape(label)}</option>`).join('');
 const config=()=>({op:$('operation').value,days:Number($('window').value),today:data.meta.asOf});
 const filters=()=>({school:$('school').value,classId:$('class').value,grade:$('grade').value,search:role==='district'?'':$('search').value});
 const students=()=>selectStudents(data,filters()).filter(s=>!group||group.students.includes(s.id));
 const metric=(value,label,caption,warning=false)=>`<article class="metric ${warning?'warning':''}"><div class="value">${escape(value)}</div><p>${label}</p><small>${caption}</small></article>`;
 const bar=n=>`<span class="bar" aria-hidden="true"><i style="width:${n??0}%"></i></span>`;
 function classOptions(){const previous=$('class').value,items=data.classes.filter(c=>$('school').value==='all'||c.schoolId===$('school').value);$('class').innerHTML=options([['all','All classrooms'],...items.map(c=>[c.id,c.name])]);if(items.some(c=>c.id===previous))$('class').value=previous;}
 function summary(){const list=students(),c=config(),m=metrics(data,list,c);$('metrics').innerHTML=metric(m.students,'Students in view',`${m.active} practiced in the last 7 days`)+metric(display(m.confirmedRate),'Assigned facts confirmed',`${m.counts.Confirmed.toLocaleString()} / ${m.totalFacts.toLocaleString()} student-fact records`)+metric(`${m.checks} / ${m.students}`,'Current check coverage',`${m.missing} missing; not scored as zero`,m.missing>0)+metric(m.due.toLocaleString(),'Fact reviews due',`${m.refresh} previously confirmed facts need refresh`);
 $('status').textContent=`${group?'Fact group: '+group.text+' · ':''}${list.length} sample students · ${NAMES[c.op]} · ${c.days}-day check window · 3 seconds per practice card`;
 $('title').textContent=({teacher:'What should I teach next?',school:'Where does our school need support?',district:'Foundational fluency. One district view.'})[role];$('scope').textContent=({teacher:'CLASSROOM INSIGHT',school:'SCHOOL SUPPORT',district:'DISTRICT PERSPECTIVE'})[role];$('subtitle').textContent=role==='district'?data.meta.district:`${schoolMap.get($('school').value)?.name||'All sample schools'} · ${classMap.get($('class').value)?.name||'All classrooms'}`;
 $('clear-group').hidden=!group;$('priority-title').textContent=role==='teacher'?'Your next small group':'Shared instructional priorities';const ps=priorities(data,list,c.op);$('priorities').innerHTML=ps.length?ps.slice(0,3).map(p=>`<button class="fact-priority" data-group="${escape(p.id)}"><span class="fact-chip">${escape(p.text)} = ${p.answer}</span><span><strong>${p.students.length} students need a closer look</strong><small>Learning or refreshing · open suggested group</small></span><b>↗</b></button>`).join(''):'<p class="empty">No learning-pool facts in this selection.</p>';
 $('priorities').querySelectorAll('[data-group]').forEach(b=>onDynamic(b,'click',()=>{group=ps.find(p=>p.id===b.dataset.group);role='teacher';setRoleButtons();render();$('table-title').scrollIntoView({block:'nearest',behavior:'smooth'});}));
 const g=growth(data,list,c.op==='all'?'mixed':c.op,c.days),first=g.points[0],last=g.points.at(-1);$('growth').innerHTML=g.matched?`<div class="growth-value">${display(first.rate)} <span>→</span> ${display(last.rate)}</div><span class="gain ${g.change<0?'negative':''}">${g.change>0?'+':''}${g.change} percentage points</span><p class="caption">Students confirming their full assigned set. Same ${g.matched} students at both endpoints; not the average percent of facts confirmed.</p><div class="growth-dates">${g.points.map(p=>`<div><span>${escape(p.date)}</span><strong>${display(p.rate)}</strong></div>`).join('')}</div>`:'<p class="empty">Not enough matched snapshots for this window.</p>';
 $('pools').innerHTML=STAGES.map(s=>`<div class="pool"><b>${m.counts[s].toLocaleString()}</b>${s}</div>`).join('');$('check-summary').innerHTML=`<div class="check-numbers"><div><b>${m.medianCorrect??'Not taken'}</b><span>median correct / 90 seconds</span></div><div><b>${display(m.medianAccuracy)}</b><span>median individual accuracy</span></div></div><div class="mini-tags"><span>${m.wrong} incorrect</span><span>${m.timeout} timeouts</span><span>${m.missing} missing checks</span></div>`;
 table(list);$('export').disabled=false;
 }
 function table(list){const c=config();$('table-title').textContent=group?`Suggested group: ${group.text}`:({teacher:'Your classroom',school:'Classroom support view',district:'Schools at a glance'})[role];$('table-count').textContent=`${list.length} students`;
 if(role==='teacher'){$('table-head').innerHTML='<tr><th>Student</th><th>Learning</th><th>Strengthening</th><th>Provisional</th><th>Confirmed facts</th><th>Latest check</th><th>Next step</th></tr>';$('table-body').innerHTML=list.map(s=>{const m=metrics(data,[s],c);return `<tr><td><button class="row-link" data-student="${escape(s.id)}">${escape(s.name)}</button><div class="subline">${escape(classMap.get(s.classId).name)}</div></td><td>${m.counts.Learning}</td><td>${m.counts.Strengthening}</td><td>${m.counts.Provisional}</td><td>${m.counts.Confirmed} / ${m.totalFacts}${bar(m.confirmedRate)}</td><td>${m.checks?`${m.medianCorrect} correct · ${display(m.medianAccuracy)}`:'Not taken'}</td><td>${m.refresh?'Revisit retained facts':!m.checks?'Complete a current check':m.counts.Learning?'Plan fact instruction':'Continue spaced review'}</td></tr>`;}).join('');$('table-caption').textContent='Open a student to inspect operation-level records, individual facts, response history and check evidence. Learning includes facts not yet seen.';
 }else{const groups=role==='district'?data.schools:data.classes.filter(x=>$('school').value==='all'||x.schoolId===$('school').value);$('table-head').innerHTML=`<tr><th>${role==='district'?'School':'Classroom'}</th><th>Students</th><th>Confirmed fact rate</th><th>Full-set retention</th><th>Check coverage</th><th>Median check</th></tr>`;$('table-body').innerHTML=groups.map(x=>{const subset=list.filter(s=>role==='district'?s.schoolId===x.id:s.classId===x.id);if(!subset.length)return '';const m=metrics(data,subset,c);return `<tr><td><button class="row-link" data-drill="${escape(x.id)}">${escape(x.name)} ↗</button></td><td>${m.students}</td><td>${display(m.confirmedRate)}${bar(m.confirmedRate)}</td><td>${m.complete} / ${m.students}</td><td>${m.checks} / ${m.students}</td><td>${m.medianCorrect??'No check'}${m.checks?' · '+display(m.medianAccuracy):''}</td></tr>`;}).join('');$('table-caption').textContent='Compare like pathways, grade levels and time windows. These groups have different cohorts; this is a support view, not a school ranking.';}
 if(!$('table-body').children.length)$('table-body').innerHTML='<tr><td colspan="7" class="empty">No students match these filters. Choose another grade or clear the search.</td></tr>';
 $('table-body').querySelectorAll('[data-student]').forEach(b=>onDynamic(b,'click',()=>openStudent(b.dataset.student)));$('table-body').querySelectorAll('[data-drill]').forEach(b=>onDynamic(b,'click',()=>{if(role==='district'){$('school').value=b.dataset.drill;classOptions();role='school';}else{$('class').value=b.dataset.drill;role='teacher';}setRoleButtons();render();}));
 }
 function openStudent(id){selectedId=id;const s=data.students.find(s=>s.id===id),c=config(),states=data.factStates.filter(f=>f.studentId===id&&(c.op==='all'||factMap.get(f.factId).op===c.op));$('detail-body').innerHTML=`<p class="eyebrow">ONE CONTINUOUS LEARNING RECORD</p><h2 id="detail-title">${escape(s.name)}</h2><p>${escape(schoolMap.get(s.schoolId).name)} · ${escape(classMap.get(s.classId).name)} · Fictional student</p><div class="detail-operations">${OPS.map(op=>{const m=metrics(data,[s],{...c,op});return `<div class="detail-operation">${NAMES[op]}<strong>${display(m.confirmedRate)}</strong>${m.counts.Confirmed} / ${m.totalFacts} facts confirmed</div>`;}).join('')}</div><div class="section-heading"><h3>Individual facts · ${NAMES[c.op]}</h3><label>Show <select id="fact-filter"><option value="all">All states</option>${STAGES.map(x=>`<option>${x}</option>`).join('')}</select></label></div><div class="detail-facts table-scroll"><table><thead><tr><th>Fact</th><th>Status</th><th>Stage</th><th>Next review</th><th>Evidence</th></tr></thead><tbody id="fact-rows"></tbody></table></div><p class="caption">Stage 0 can mean not yet seen. A prior correct response alone does not prove retention. All fixture states are illustrative, not inferred from the short response sample below.</p><section class="detail-section"><h3 id="fact-history-title">Recent response sample · 7 × 8</h3><ul id="fact-history" class="history"></ul></section><section class="detail-section"><h3>Official check evidence</h3><p class="caption">Valid official checks only. Stored rule version: pilot-1. No trophy or tier is awarded by this dashboard.</p><div class="table-scroll"><table><thead><tr><th>Date</th><th>Pathway</th><th>Correct / attempted</th><th>Accuracy</th><th>Incorrect</th><th>Timeout</th></tr></thead><tbody>${data.checks.filter(x=>x.studentId===id&&x.valid&&x.official&&(c.op==='all'||x.pathway===c.op)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,15).map(x=>`<tr><td>${x.date}</td><td>${escape(x.pathway==='mixed'?'Mixed':NAMES[x.pathway])}</td><td>${x.correct} / ${x.attempted}</td><td>${Math.round(100*x.correct/x.attempted)}%</td><td>${x.incorrect}</td><td>${x.timeouts}</td></tr>`).join('')||'<tr><td colspan="6">No official check records.</td></tr>'}</tbody></table></div></section>`;
 const drawFacts=()=>{const selected=$('fact-filter').value;$('fact-rows').innerHTML=states.filter(f=>selected==='all'||status(f)===selected).map(f=>{const q=factMap.get(f.factId);return `<tr><td>${escape(q.text)} = ${q.answer}</td><td>${status(f)}${f.refresh?' · refresh':''}</td><td>${f.stage} / 4</td><td>${f.due||'Not scheduled'}</td><td><button class="fact-action" data-fact="${escape(f.factId)}">View history</button></td></tr>`;}).join('')||'<tr><td colspan="5">No facts in this status.</td></tr>';$('fact-rows').querySelectorAll('[data-fact]').forEach(b=>onDynamic(b,'click',()=>showHistory(b.dataset.fact)));};onDynamic($('fact-filter'),'change',drawFacts);drawFacts();const firstWithEvidence=states.find(f=>data.responses.some(r=>r.studentId===id&&r.factId===f.factId&&!r.demo));showHistory((firstWithEvidence||states[0]).factId);$('detail').showModal();
 }
 function showHistory(factId){const q=factMap.get(factId);$('fact-history-title').textContent=`Response sample · ${q?.text||factId}`;const rows=data.responses.filter(r=>r.studentId===selectedId&&r.factId===factId&&!r.demo).sort((a,b)=>b.date.localeCompare(a.date));$('fact-history').innerHTML=rows.length?rows.map(r=>`<li><strong>${escape(r.date)} · ${escape(r.outcome)}</strong> · ${escape(gameNames[r.game]||r.game)} · ${(r.elapsedMs/1000).toFixed(2)}s${r.assisted?' · assisted':''}</li>`).join(''):'<li>No response sample supplied for this fact. State is provided by the reporting source; do not invent missing evidence.</li>';}
 function setRoleButtons(){root.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.role===role)));(root.body||root.host||root).dataset.role=role;}
 function render(){summary();}
 function setRole(next){role=next;group=null;$('search').value='';$('grade').value='all';$('school').value=next==='district'?'all':data.schools[0].id;classOptions();$('class').value=next==='teacher'?data.classes[0].id:'all';setRoleButtons();render();}
 try{data=validate(await adapter.load({signal:controller.signal}));if(controller.signal.aborted)return;schoolMap=names('schools');classMap=names('classes');factMap=names('facts');$('school').innerHTML=options([['all','All schools'],...data.schools.map(s=>[s.id,s.name])]);$('grade').innerHTML=options([['all','All grades'],...[...new Set(data.students.map(s=>s.grade))].sort((a,b)=>a-b).map(g=>[g,'Grade '+g])]);$('asof').textContent='Sample records as of '+data.meta.asOf+'.';
 root.querySelectorAll('[data-role]').forEach(b=>on(b,'click',()=>setRole(b.dataset.role)));on($('school'),'change',()=>{group=null;classOptions();render();});for(const id of ['class','grade','operation','window'])on($(id),'change',()=>{group=null;render();});on($('search'),'input',()=>{group=null;render();});on($('filters'),'submit',e=>e.preventDefault());on($('clear-group'),'click',()=>{group=null;render();});on($('close-detail'),'click',()=>$('detail').close());on($('definitions'),'click',()=>$('measure-dialog').showModal());on($('close-measures'),'click',()=>$('measure-dialog').close());
 on($('export'),'click',()=>{const c=config(),rows=[['FICTIONAL SAMPLE DATA','as of',data.meta.asOf,'pathway',c.op,'window days',c.days],['School','Class','Student','Learning','Strengthening','Provisional','Confirmed','Assigned facts','Latest official check correct','Latest official check accuracy']];for(const s of students()){const m=metrics(data,[s],c);rows.push([schoolMap.get(s.schoolId).name,classMap.get(s.classId).name,s.name,m.counts.Learning,m.counts.Strengthening,m.counts.Provisional,m.counts.Confirmed,m.totalFacts,m.medianCorrect,m.medianAccuracy]);}const url=URL.createObjectURL(new Blob([csv(rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`fluency-sample-${role}-${c.op}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});setRole(role);
 }catch(error){$('status').textContent='Could not load reporting records. '+error.message;$('status').setAttribute('role','alert');}
 return {destroy(){controller.abort();listeners.forEach(fn=>fn());root.querySelectorAll('button').forEach(b=>b.onclick=null);for(const id of ['detail','measure-dialog'])if($(id).open)$(id).close();}};
}
